    if (k === AP_KEY) Object.keys(b).forEach(a => { const gk = Object.keys(g).find(x => x.toLowerCase() === a.toLowerCase()); if (!gk) return; const keep = ((b[a] && b[a].t) || 0) > ((g[gk] && g[gk].t) || 0) ? [a, b[a]] : [gk, g[gk]]; delete o[a]; delete o[gk]; o[keep[0]] = keep[1]; });
