    Object.keys(pc).filter(k => !ne(k)).forEach(k => { ((pc[k] && pc[k].pets) || []).forEach(p => gone.push(String(p.name).toLowerCase())); delete pc[k]; });
    gmSet(AP_KEY, pc);
