      const apSaveTag = (k, patch) => {
        const t = apTags(), cur = t[k] || {};
        if ('s' in patch) cur.s = patch.s;
        if ('n' in patch) cur.n = patch.n.trim().slice(0, 60);
        if (!cur.s && !cur.n) delete t[k]; else t[k] = cur;
        gmSet(AP_TAGS, t);
      };
